"use client";

import { useRef } from "react";
import { Sphere, useTexture } from "@react-three/drei";
import * as THREE from "three";

export default function LegacyPlanetVisual() {
  const meshRef = useRef<THREE.Mesh>(null);

  // 🧠 تحميل صورتك المخصصة
  const texture = useTexture("/textures/planets/legacy/default/albedo.jpg");

  return (
    <group>
      {/* 🏀 جسم كرة السلة */}
      <Sphere ref={meshRef} args={[1, 64, 64]}>
        <meshStandardMaterial
          map={texture}           // 👈 الصورة الملونة بالتوقيعات
          bumpMap={texture}       // 👈 سحر الـ 3D: استخدام الصورة لعمل بروز الجلد
          bumpScale={0.015}       // قوة البروز (نتوءات خفيفة تحاكي الجلد الحقيقي)
          roughness={0.85}        // ملمس خشن غير لامع كالجلد
          metalness={0.1}         // انعكاس طفيف جداً للضوء
          color="#ffffff"         // أبيض للحفاظ على ألوان صورتك الأصلية دون تغيير
        />
      </Sphere>

      {/* 🛰️ حلقة سينمائية خفيفة تدور حول الكرة لتعطي طابع الخيال العلمي */}
      <mesh rotation={[Math.PI / 2, 0, 0]}>
        <torusGeometry args={[1.3, 0.005, 16, 100]} />
        <meshBasicMaterial color="#ffffff" transparent opacity={0.1} />
      </mesh>
    </group>
  );
}